struct stringx {
  char data[8];
};

class entity;

struct value_type {
  const stringx first;
  entity *second;
};

struct node {
  int color;
  node *parent;
  node *left;
  node *right;
  value_type value;
};

struct iterator {
  node *_M_node;

  iterator& operator--() {
    if (_M_node->color == 0 &&
        _M_node->parent->parent == _M_node)
      _M_node = _M_node->right;
    else if (_M_node->left != 0) {
      node *y = _M_node->left;
      while (y->right != 0)
        y = y->right;
      _M_node = y;
    } else {
      node *y = _M_node->parent;
      while (_M_node == y->left) {
        _M_node = y;
        y = y->parent;
      }
      _M_node = y;
    }
    return *this;
  }
};

struct result {
  iterator first;
  bool second;

  result(const iterator& x, const bool& y) : first(x), second(y) {}
};

struct tree {
  node *_M_header;
  unsigned int _M_node_count;
};

