result insert_unique_value(tree *self, const value_type &v) {
  node *y = self->_M_header;
  node *x = self->_M_header->parent;
  bool comp = true;
  while (x != 0) {
    y = x;
    comp = stringx_less(v.first, x->value.first);
    x = comp ? x->left : x->right;
  }
  iterator j;
  j._M_node = y;
  if (comp)
    if (j._M_node == self->_M_header->left)
      return result(tree_insert(self, x, y, v), true);
    else
      --j;
  if (stringx_less(j._M_node->value.first, v.first))
    return result(tree_insert(self, x, y, v), true);
  return result(j, false);
}
